ssize_t sound_timer_read(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    ssize_t bytes_read = 0;

    if (!file || !buffer || !offset) {
        return -EINVAL;
    }

    if (!try_module_get(THIS_MODULE)) {
        return -EFAULT;
    }

    mutex_lock(&device_mutex);
    spin_lock(&device_spinlock);

    if (queue_is_empty()) {
        mutex_unlock(&device_mutex);
        spin_unlock(&device_spinlock);
        module_put(THIS_MODULE);
        return -EAGAIN;
    }

    while (bytes_read < count && !queue_is_empty()) {
        char data = dequeue_data();
        if (data == '\0') {
            break;
        }

        if (copy_to_user(buffer + bytes_read, &data, 1)) {
            mutex_unlock(&device_mutex);
            spin_unlock(&device_spinlock);
            module_put(THIS_MODULE);
            return -EFAULT;
        }

        bytes_read++;
    }

    spin_unlock(&device_spinlock);
    mutex_unlock(&device_mutex);

    if (bytes_read == 0 && is_device_disconnected()) {
        module_put(THIS_MODULE);
        return -ENODEV;
    }

    *offset += bytes_read;

    module_put(THIS_MODULE);
    return bytes_read;
}

