ssize_t read_sound_timer_data(struct file *file, char __user *buffer, size_t count, loff_t *offset)
{
    ssize_t bytes_read = 0;
    int result;

    if (!buffer || !offset) {
        return -EINVAL;
    }

    if (!file) {
        return -EBADF;
    }

    if (count <= 0) {
        return 0;
    }

    mutex_lock(&device_mutex);
    spin_lock(&device_spinlock);

    if (sound_timer_queue_empty()) {
        if (file->f_flags & O_NONBLOCK) {
            spin_unlock(&device_spinlock);
            mutex_unlock(&device_mutex);
            return -EAGAIN;
        }

        while (sound_timer_queue_empty()) {
            wait_event_interruptible(sound_timer_wait_queue, !sound_timer_queue_empty());
        }
    }

    while (bytes_read < count && !sound_timer_queue_empty()) {
        char data;
        result = sound_timer_read_data(&data);
        if (result < 0) {
            spin_unlock(&device_spinlock);
            mutex_unlock(&device_mutex);
            return result;
        }

        if (copy_to_user(buffer + bytes_read, &data, 1)) {
            spin_unlock(&device_spinlock);
            mutex_unlock(&device_mutex);
            return -EFAULT;
        }

        bytes_read++;
    }

    *offset += bytes_read;

    spin_unlock(&device_spinlock);
    mutex_unlock(&device_mutex);

    return bytes_read;
}

ssize_t sound_timer_read(struct file *file, char __user *buffer, size_t count, loff_t *offset)
{
    ssize_t bytes_read = 0;
    int result;

    if (!file || !buffer || count == 0 || !offset)
        return -EINVAL;

    /* Acquire the device's mutex for thread safety */
    mutex_lock(&sound_timer_dev.mutex);

    /* Acquire the spinlock to ensure atomic operations on the queue */
    spin_lock(&sound_timer_dev.spinlock);

    /* Check if there is data available in the queue */
    if (sound_timer_dev.queue_head == sound_timer_dev.queue_tail) {
        /* No data available, unlock and wait */
        spin_unlock(&sound_timer_dev.spinlock);
        mutex_unlock(&sound_timer_dev.mutex);

        if (file->f_flags & O_NONBLOCK)
            return -EAGAIN;

        /* Wait for data to become available */
        result = wait_event_interruptible(sound_timer_dev.wait_queue,
                                          sound_timer_dev.queue_head != sound_timer_dev.queue_tail);
        if (result < 0) {
            /* Error or signal occurred during wait */
            return result;
        }

        /* Re-acquire the mutex and spinlock after waiting */
        mutex_lock(&sound_timer_dev.mutex);
        spin_lock(&sound_timer_dev.spinlock);
    }

    /* Read data from the queue into the user buffer */
    while (bytes_read < count && sound_timer_dev.queue_head != sound_timer_dev.queue_tail) {
        char data = sound_timer_dev.queue[sound_timer_dev.queue_tail];
        if (copy_to_user(buffer + bytes_read, &data, 1) != 0) {
            spin_unlock(&sound_timer_dev.spinlock);
            mutex_unlock(&sound_timer_dev.mutex);
            return -EFAULT;
        }

        sound_timer_dev.queue_tail = (sound_timer_dev.queue_tail + 1) % SOUND_TIMER_QUEUE_SIZE;
        bytes_read++;
    }

    spin_unlock(&sound_timer_dev.spinlock);
    mutex_unlock(&sound_timer_dev.mutex);

    if (bytes_read == 0 && sound_timer_dev.disconnected)
        return -ENODEV;

    return bytes_read;
}
